import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadChannapatnaData(){const e=readFileSync(resolve(__dirname,"../../channapatna-toys-explorer/channapatna-data.js"),"utf-8");return new Function(e+"\nreturn { CHANNAPATNA_INFO, HISTORY_CHAPTERS, CRAFTING_PROCESS, SUSTAINABLE_MATERIALS, TRADITIONAL_DESIGNS, ARTISAN_COMMUNITY, GALLERY_IMAGES, REFERENCES };")()}describe("Channapatna Toys Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadChannapatnaData()}),describe("CHANNAPATNA_INFO metadata",()=>{it("contains correct Channapatna metadata and GI tag",()=>{expect(e.CHANNAPATNA_INFO.id).toBe("channapatna-toys"),expect(e.CHANNAPATNA_INFO.title).toContain("Channapatna"),expect(e.CHANNAPATNA_INFO.originRegion).toContain("Karnataka"),expect(e.CHANNAPATNA_INFO.giTagStatus).toContain("GI")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.CHANNAPATNA_INFO.quickStats)).toBe(!0),expect(e.CHANNAPATNA_INFO.quickStats.length).toBe(6)})}),describe("HISTORY_CHAPTERS & CRAFTING_PROCESS",()=>{it("contains history chapters and crafting process steps",()=>{expect(Array.isArray(e.HISTORY_CHAPTERS)).toBe(!0),expect(e.HISTORY_CHAPTERS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.CRAFTING_PROCESS)).toBe(!0),expect(e.CRAFTING_PROCESS.length).toBeGreaterThanOrEqual(5)})}),describe("SUSTAINABLE_MATERIALS & TRADITIONAL_DESIGNS",()=>{it("contains sustainable materials and traditional designs",()=>{expect(Array.isArray(e.SUSTAINABLE_MATERIALS)).toBe(!0),expect(e.SUSTAINABLE_MATERIALS.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.TRADITIONAL_DESIGNS)).toBe(!0),expect(e.TRADITIONAL_DESIGNS.length).toBeGreaterThanOrEqual(4)})}),describe("ARTISAN_COMMUNITY",()=>{it("contains artisan community details",()=>{expect(e.ARTISAN_COMMUNITY.title).toBeDefined(),expect(e.ARTISAN_COMMUNITY.description).toContain("Channapatna")})}),describe("GALLERY_IMAGES & REFERENCES",()=>{it("has non-empty gallery and references",()=>{expect(Array.isArray(e.GALLERY_IMAGES)).toBe(!0),expect(e.GALLERY_IMAGES.length).toBeGreaterThanOrEqual(2),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});